```

## image_gen
Tools in the image_gen namespace.

### `image_gen__imagegen`
The `image_gen.imagegen` tool enables image generation from descriptions and editing of existing images based on specific instructions. Use it when:

- The user requests an image based on a scene description, such as a diagram, portrait, comic, meme, or any other visual.
- The user wants to modify an attached or previously generated image with specific changes, including adding or removing elements, altering colors, improving quality/resolution, or transforming the style (e.g., cartoon, oil painting).

Guidelines:
- imagegen needs a few minutes to finish. In code-mode, use the first-line @exec directive to give the initial call 120 seconds and the same yield for any waits that follow. Once it finishes, return the image with generatedImage(result).
- Avoid printing the full result or its base64 image data with `text()` or `notify()`; print only small metadata when needed.
- Set `transparent_background` to true when the request calls for a transparent background, including background removal or a cutout; set it to false otherwise. For edits, preserve existing transparency unless the user asks to change it.
- Omit both `referenced_image_paths` and `num_last_images_to_include` when generating a brand new image.
- For edits, use `referenced_image_paths` when every target image has a local file path.
- If you have not seen a local image yet, use `view_image` to inspect it before editing.
- Use `num_last_images_to_include` only when at least one target image has no local file path.
- Set `num_last_images_to_include` to the smallest number of recent conversation images that includes every target image, up to 5.
- Never provide both `referenced_image_paths` and `num_last_images_to_include`.
- If neither mechanism can include every target image, ask the user to attach the missing images again.
- Directly generate the image without reconfirmation or clarification unless required images must be attached again.
- Always use this tool for image editing unless the user explicitly requests otherwise. Do not use the `python` tool for image editing unless specifically instructed.


exec tool declaration:
```ts
declare const tools: { image_gen__imagegen(args: {
  num_last_images_to_include?: number | null;
  prompt: string;
  referenced_image_paths?: Array<string> | null;
  // Whether the output should have a transparent background. Defaults to false.
  transparent_background?: boolean;
}): Promise<{ image_url: string; output_hint?: string; }>; };
```

item.aggregated_output:
// A local graphical consumer for the existing queue modules, not an asset generator.
import { createServer } from 'node:http';
import { readFile, realpath } from 'node:fs/promises';
import { resolve, relative, sep, dirname, extname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { stripTypeScriptTypes } from 'node:module';
import { createHash } from 'node:crypto';

export const rendererRoot = dirname(fileURLToPath(import.meta.url));
export const hash = bytes => createHash('sha256').update(bytes).digest('hex');

export async function serve(project, onCapture = null) {
  const root = await realpath(project);
  const served = new Map();
  const server = createServer(async (request, response) => {
    try {
      const url = new URL(request.url, 'http://127.0.0.1');
      if (url.pathname === '/__capture' && request.method === 'POST' && onCapture) {
        let body = '';
        for await (const chunk of request) {
          body += chunk;
          if (body.length > 4_000_000) throw new Error('Capture exceeds local limit');
        }
        await onCapture(JSON.parse(body));
        response.writeHead(200, { 'Content-Type': 'text/plain' }).end('retained');
        return;
      }
      if (request.method !== 'GET') {
        response.writeHead(405).end();
        return;
      }
      const pathname = decodeURIComponent(url.pathname);
      const own = pathname === '/' || pathname === '/view.mjs';
      if (!own && !pathname.startsWith('/src/') && !pathname.startsWith('/assets/')) {
        response.writeHead(404).end('Not a consumer resource');
        return;
      }
      const base = own ? rendererRoot : root;
      const name = pathname === '/' ? 'index.html' : pathname.slice(1);
      const path = await realpath(resolve(base, name));
      const rel = relative(base, path);
      if (rel === '..' || rel.startsWith(`..${sep}`) || resolve(base, rel) !== path) {
        response.writeHead(403).end('Outside consumer');
        return;
      }
      const bytes = await readFile(path);
      served.set(`${own ? 'renderer' : 'consumer'}/${rel.replaceAll(sep, '/')}`, hash(bytes));
      const extension = extname(path);
      const type = { '.html': 'text/html', '.mjs': 'text/javascript', '.ts': 'text/javascript', '.png': 'image/png', '.svg': 'image/svg+xml' }[extension];
      if (!type) { response.writeHead(415).end(); return; }
      response.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-store' });
      response.end(extension === '.ts' ? stripTypeScriptTypes(bytes.toString('utf8')) : bytes);
    } catch (error) {
      const missing = error.code === 'ENOENT';
      response.writeHead(missing ? 404 : 500).end(missing ? 'Missing consumer asset' : String(error));
    }
  });
  await new Promise((yes, no) => { server.once('error', no); server.listen(0, '127.0.0.1', yes); });
  return { server, root, served, url: `http://127.0.0.1:${server.address().port}` };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const flag = process.argv.indexOf('--project');
  const project = flag < 0 ? resolve(rendererRoot, '..') : resolve(process.argv[flag + 1]);
  const running = await serve(project);
  console.log(JSON.stringify({ url: running.url, project: running.root, node: process.version }));
}
// Fresh isolated browser capture. No production/profile-wide browser configuration.
import { spawn } from 'node:child_process';
import { access, mkdir, readFile, writeFile, mkdtemp, realpath, rm } from 'node:fs/promises';
import { resolve, join, relative, sep } from 'node:path';
import { tmpdir } from 'node:os';
import { serve, rendererRoot, hash } from './server.mjs';

const option = name => { const i = process.argv.indexOf(name); return i < 0 ? null : process.argv[i + 1]; };
const project = resolve(option('--project') || join(rendererRoot, '..'));
const output = option('--out');
if (!output) throw new Error('Use --out NEW_DIRECTORY to retain a fresh capture');
const out = resolve(output);
await mkdir(out, { recursive: false });
let browser = option('--browser');
if (!browser) {
  for (const file of [join(process.env.PROGRAMFILES || '', 'Google/Chrome/Application/chrome.exe'), join(process.env['ProgramFiles(x86)'] || '', 'Microsoft/Edge/Application/msedge.exe')]) {
    try { await access(file); browser = file; break; } catch { /* Try next installed browser. */ }
  }
}
if (!browser) throw new Error('No local Chromium browser found; pass --browser PATH');
const profileParent = await realpath(tmpdir());
const profile = await mkdtemp(join(profileParent, 'pixl-render-'));
const rendererFiles = Object.fromEntries(await Promise.all(['server.mjs', 'capture.mjs', 'index.html', 'view.mjs', 'check.py'].map(async name => [name, hash(await readFile(join(rendererRoot, name)))])));
let observed;
const running = await serve(project, report => { if (observed) throw new Error('Duplicate capture'); observed = report; });
const args = ['--headless=new', '--disable-gpu', '--hide-scrollbars', '--no-first-run', '--no-default-browser-check', '--disable-background-networking', '--force-device-scale-factor=1', `--user-data-dir=${profile}`, '--window-size=1280,1000', '--virtual-time-budget=4000', '--run-all-compositor-stages-before-draw', `--screenshot=${join(out, 'destination.png')}`, `${running.url}/?capture=1`];
await writeFile(join(out, 'launch.json'), JSON.stringify({ browser, args, project, node: process.version, scope: 'Isolated local fixture renderer' }, null, 2) + '\n');
let processResult;
try {
  processResult = await new Promise((yes, no) => {
    const child = spawn(browser, args, { windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '', stderr = '';
    child.stdout.on('data', chunk => { stdout += chunk; }); child.stderr.on('data', chunk => { stderr += chunk; });
    const timer = setTimeout(() => { child.kill(); no(new Error('Browser capture exceeded 45 seconds')); }, 45_000);
    child.once('error', error => { clearTimeout(timer); no(error); });
    child.once('exit', code => { clearTimeout(timer); yes({ code, stdout, stderr }); });
  });
  await writeFile(join(out, 'browser-process.json'), JSON.stringify(processResult, null, 2) + '\n');
  if (processResult.code !== 0 || !observed) throw new Error('Browser did not return a complete capture');
  const screenshot = await readFile(join(out, 'destination.png'));
  let index = 0;
  for (const item of [...observed.views, ...observed.timeline]) if (item.png) {
    const bytes = Buffer.from(item.png.split(',')[1], 'base64');
    const name = `view-${String(index++).padStart(3, '0')}.png`;
    await writeFile(join(out, name), bytes); item.image = { path: name, sha256: hash(bytes) }; delete item.png;
  }
  observed.served_files = Object.fromEntries(running.served);
  for (const [name, expected] of Object.entries(rendererFiles)) if (hash(await readFile(join(rendererRoot, name))) !== expected) throw new Error(`Renderer changed during capture: ${name}`);
  observed.renderer_files = rendererFiles;
  observed.screenshot = { path: 'destination.png', sha256: hash(screenshot) };
  observed.observed_at = new Date().toISOString();
  await writeFile(join(out, 'render.json'), JSON.stringify(observed, null, 2) + '\n');
  console.log(JSON.stringify({ capture: join(out, 'render.json'), screenshot: join(out, 'destination.png'), missing: observed.missing, errors: observed.errors }));
} finally {
  running.server.closeAllConnections(); await new Promise(yes => running.server.close(yes));
  // Only remove this process's own resolved temporary profile, never a user profile.
  const actual = await realpath(profile);
  const within = relative(profileParent, actual);
  if (within.startsWith('pixl-render-') && !within.includes(sep) && actual === resolve(profile)) {
    try { await rm(actual, { recursive: true, maxRetries: 4, retryDelay: 250 }); } catch { /* OS-held cache may outlive the browser. */ }
  }
}
import { stateAfter } from '/src/queue.ts';
import { statusVisuals, statusCell, compactStatus, display } from '/src/queue-view.ts';

const panel = display.background;
document.documentElement.style.setProperty('--panel', panel);
const cache = new Map();
const cells = [];
const consumers = { statusCell, compactStatus };
const events = ['idle', 'started', 'pause', 'ok', 'error'].filter(event => event === 'idle' || statusVisuals[stateAfter(event)]);
document.querySelectorAll('[data-event]').forEach(button => { button.hidden = !events.includes(button.dataset.event); });
const errors = [];
window.addEventListener('error', event => errors.push(event.message));
window.addEventListener('unhandledrejection', event => errors.push(String(event.reason)));
const digest = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(x => x.toString(16).padStart(2, '0')).join('');

async function imageFor(path) {
  if (!cache.has(path)) cache.set(path, (async () => {
    const response = await fetch(`/${path}`);
    if (!response.ok) return { available: false, status: response.status, path };
    const data = await response.arrayBuffer();
    const image = new Image();
    const url = URL.createObjectURL(new Blob([data], { type: response.headers.get('Content-Type') }));
    try { image.src = url; await image.decode(); }
    finally { URL.revokeObjectURL(url); }
    return { available: true, image, path, sha256: await digest(data), width: image.naturalWidth, height: image.naturalHeight };
  })());
  return cache.get(path);
}

function paint(canvas, asset, frames, scale, elapsed) {
  const [width, height] = display.cell;
  const frame = Math.floor(Math.max(elapsed, 0) / display.frameMs) % frames;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  context.imageSmoothingEnabled = display.filter !== 'nearest';
  context.fillStyle = panel;
  context.fillRect(0, 0, canvas.width, canvas.height);
  if (asset.available && asset.width === width * frames && asset.height === height) {
    context.drawImage(asset.image, frame * width, 0, width, height, 0, 0, width * scale, height * scale);
  }
  return frame;
}

async function makeCell(consumer, state, scale, elapsed = 0, track = true) {
  const descriptor = consumers[consumer](state);
  const asset = await imageFor(descriptor.path);
  const node = document.createElement('div');
  node.className = `cell ${consumer === 'compactStatus' ? 'compact' : ''}`;
  const glyph = document.createElement('span'); glyph.className = 'glyph';
