const rr=await tools.exec_command({cmd:"Get-Content -Raw -Encoding utf8 authoring-plar.txt",max_output_tokens:25000});const doc=JSON.parse(rr.output);
await tools.apply_patch("*** Begin Patch
*** Add File: work/focused-successor/plar-before.json
+"+rr.output.trim().replaceAll("
","
+")+"
*** End Patch");
const changes=[];
for(const a of doc.assets.filter(a=>["queue.working","queue.retry","queue.paused"].includes(a.id))){for(const e of a.existing||[]){if(/missing|no .*supplied/.test(e.role)){changes.push({asset:a.id,field:"existing.role",before:e.role});e.role="Existing original-production artwork is present and retained unchanged. Exact-byte successor copies and fresh local renderer evidence are recorded in work/focused-successor/reuse-copy.json and caller-comparison.json; old acceptance is not transferred to authoring or successor criteria.";changes.at(-1).after=e.role;}}
a.delivery.checks=a.delivery.checks.map(v=>{if(/no .*artwork exists|neither has been completed for Paused/.test(v)){const next="Retain fresh visual review and integration evidence separately from mechanical checks. Original-production artwork and its earlier acceptance exist; this authoring allocation and the reviewed successor do not inherit that acceptance. Fresh local successor evidence is work/focused-successor/caller-comparison.json; retained-generation completion remains open.";changes.push({asset:a.id,field:"delivery.checks observational prose",before:v,after:next});return next;}return v;});
if(a.id==="queue.working"){const ob=a.requirements.find(r=>r.property==="renderer_frame_extraction");changes.push({asset:a.id,field:"renderer_frame_extraction observation",before:JSON.parse(JSON.stringify(ob))});ob.value.working_result="Original-production Working cf101610108f5a708987dfeb1a86ae9921525464d24c19953a889e20603176dc exists. Old renderer implementation/source binding remains unchanged; new src/queue-view-successor.ts and renderer-successor/ use reviewed copies. render-03 proves normal cycling, stationary reduced-motion frame0 and live switching in both consumers; no new UDL generation acceptance.";ob.reason="Old fixture extraction remains an accurate source observation. Earlier absent-art and placement statements are historical; current successor measurements are in work/focused-successor/pixel-check-03.json and motion-check.json, with visual limits in caller-comparison.json.";changes.at(-1).after=ob;}
a.next="Reviewed reuse-only successor is implemented and locally rendered at src/queue-view-successor.ts and renderer-successor/. Resolve the public retained connected-plan revision interface for existing production links; do not delete links, dispatch old abandoned intent or transfer acceptance. See work/focused-successor/public-plan-attempt.json.";
a.evidence.push({path:"work/focused-successor/caller-comparison.json",note:"Fresh independent successor20criterion comparison and local browser evidence; historical generations/links unchanged, no new acceptance."});}
await tools.apply_patch("*** Begin Patch
*** Add File: work/focused-successor/plar-observation-changes.json
+"+JSON.stringify(changes,null,2).replaceAll("
","
+")+"
*** End Patch");
store("plar_changes",changes);
const r=await tools.mcp__pixl_local__pixl_plar_save({path:"authoring-plar.txt",expect:"7c6c54fb55f0cb46fb8f5707468b3776438bd62ab102beafb49c2e91e50e3b41",document:doc});store("plarsave",r.structuredContent||JSON.parse(r.content[0].text));text(load("plarsave"));
await tools.apply_patch("*** Begin Patch
*** Add File: work/focused-successor/plar-save-result.json
+"+JSON.stringify(r,null,2).replaceAll("
","
+")+"
*** End Patch");

